github_client.py:
"""Shared GitHub transport and repository operations for GitHub automations."""

import argparse
import json
import os
import re
import subprocess
from functools import cached_property
from pathlib import Path
from urllib.error import HTTPError
from urllib.parse import parse_qsl, urlencode, urlsplit
from urllib.request import Request, urlopen


# The secret name of the GitHub token an OpenHands Cloud or Enterprise user's
# connected GitHub integration provides: how this run's sandbox serves it, and
# how a conversation sees it in its environment.
CLOUD_GITHUB_TOKEN_SECRET = "github_token"
CLOUD_GITHUB_TOKEN_ENV = "GITHUB_TOKEN"


def is_cloud_run() -> bool:
    """Whether this run is on OpenHands Cloud or Enterprise.

    The automation service hands a run the Agent Server URL only on a local
    Agent Canvas; elsewhere the run talks to the OpenHands API instead.
    """
    return bool(os.environ.get("OPENHANDS_CLOUD_API_URL")) and not os.environ.get(
        "AGENT_SERVER_URL"
    )


def _load_cloud_secret(name: str) -> str | None:
    """Read one named secret of this run's sandbox from the OpenHands API."""
    api = os.environ["OPENHANDS_CLOUD_API_URL"].rstrip("/")
    request = Request(
        f"{api}/api/v1/sandboxes/{os.environ['SANDBOX_ID']}/settings/secrets/{name}",
        headers={"X-Session-API-Key": os.environ["SESSION_API_KEY"]},
    )
    try:
        with urlopen(request, timeout=90) as response:
            return response.read().decode().strip()
    except HTTPError as exc:
        if exc.code == 404:
            return None
        raise


def _load_secret(name: str) -> str:
    """Read one named secret from the environment, or from the configured Agent
    Server on a local run and the OpenHands API on a cloud one."""
    value = os.environ.get(name)
    if value:
        return value

    if is_cloud_run():
        value = _load_cloud_secret(name)
    else:
        from openhands.sdk.workspace import RemoteWorkspace

        workspace = RemoteWorkspace(
            host=os.environ["AGENT_SERVER_URL"],
            api_key=os.environ["SESSION_API_KEY"],
            working_dir=os.environ.get("WORKSPACE_BASE", "/workspace"),
        )
        try:
            secret = workspace.get_secrets([name]).get(name)
            value = secret.get_value() if secret else None
        finally:
            workspace.reset_client()
    if not value:
        raise ValueError(f"The GitHub credential {name} is unavailable")
    return value


def github_request(
    token: str,
    method: str,
    path: str,
    params: dict | None = None,
    body: dict | None = None,
    accept: str = "application/vnd.github+json",
) -> tuple:
    url = f"https://api.github.com{path}"
    if params:
        url = f"{url}?{urlencode(params)}"
    headers = {
        "Authorization": f"Bearer {token}",
        "Accept": accept,
        "X-GitHub-Api-Version": "2022-11-28",
        "Content-Type": "application/json",
    }
    data = json.dumps(body).encode() if body is not None else None
    req = Request(url, data=data, headers=headers, method=method)
    with urlopen(req, timeout=90) as r:
        raw = r.read()
        return (json.loads(raw) if raw.strip() else {}), dict(r.headers)


def github_paginate(token: str, path: str, params: dict | None = None) -> list:
    results = []
    base_params = dict(params or {})
    base_params.setdefault("per_page", 100)
    for page in range(1, 101):
        base_params["page"] = page
        data, _ = github_request(token, "GET", path, params=base_params)
        if not isinstance(data, list):
            raise TypeError("Expected a paginated GitHub list")
        results.extend(data)
        if len(data) < int(base_params["per_page"]):
            return results
    raise RuntimeError("GitHub pagination exceeded limit")


class GitHubRepository:
    name = "GitHub automation"

    def __init__(
        self,
        config_path=Path("config.json"),
        *,
        github_token_secret,
        repository=None,
        conversation=None,
        dispatcher=None,
    ):
        self.config = json.loads(Path(config_path).read_text())
        self.repository = repository or self.config["repository"]
        if not re.fullmatch(r"[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+", self.repository):
            raise ValueError("repository must be owner/repo")
        if not re.fullmatch(r"[A-Z_][A-Z0-9_]*", github_token_secret):
            raise ValueError(
                "Expected the environment variable containing the GitHub token"
            )
        self.token_name = github_token_secret
        try:
            self.token = _load_secret(github_token_secret)
        except ValueError:
            if not is_cloud_run():
                raise
            # No secret is saved under that name, so use the user's connected
            # GitHub integration, under the name a conversation sees it by.
            self.token = _load_cloud_secret(CLOUD_GITHUB_TOKEN_SECRET)
            if not self.token:
                raise
            self.token_name = CLOUD_GITHUB_TOKEN_ENV
        self.conversation = conversation
        self.conversation_id = str(conversation.id) if conversation else None
        self.dispatcher = dispatcher
        # A cloud run is not given a workspace base; its sandbox has /workspace.
        self.workspace = Path(os.environ.get("WORKSPACE_BASE", "/workspace"))
        self.project = self.workspace
        self.evidence = self.workspace / "evidence"
        self.evidence.mkdir(exist_ok=True)
        self._completed_dependencies = {}

    @cached_property
    def base_branch(self):
        return self.config.get("base_branch") or self.gh("GET", "")["default_branch"]

    @property
    def github_instructions(self):
        # A cloud conversation runs in a sandbox of its own, so this run's
        # workspace path means nothing to it.
        where = "your working directory" if is_cloud_run() else self.project
        return (
            f"Use `GH_TOKEN=${self.token_name} gh api` for GitHub requests. "
            "Never print the credential value. "
            f"Only {self.repository} is in scope. Work in {where}. "
            "Do not modify the automation bundle or its configuration."
        )

    def gh(self, method, path, body=None):
        return github_request(
            self.token, method, f"/repos/{self.repository}" + path, body=body
        )[0]

    def api(self, method, path, params=None, body=None):
        """Call a GitHub endpoint that is not scoped to one repository."""
        return github_request(self.token, method, path, params=params, body=body)[0]

    def shell(self, args, cwd=None, timeout=300):
        result = subprocess.run(
            args,
            cwd=cwd or self.project,
            text=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            timeout=timeout,
            check=False,
        )
        if result.returncode:
            raise RuntimeError(
                f"{args[0]} failed: {result.stdout[-4000:].replace(self.token, '[REDACTED]')}"
            )
        return result.stdout.strip()

    def comment(self, number, text):
        return self.gh(
            "POST",
            f"/issues/{number}/comments",
            {
                "body": text
                + f"\n\nFactory role: `{self.name}`; conversation: `{self.conversation_id}`."
                + "\n\n_This comment was posted by an AI agent (OpenHands)._"
            },
        )

    def open_issues(self):
        return [
            i for i in self.gh_pages("/issues?state=open") if "pull_request" not in i
        ]

    def statuses(self, sha):
        result = {}
        for item in self.gh_pages(f"/commits/{sha}/statuses"):
            result.setdefault(item["context"], item["state"])
        return result

    def check_runs(self, sha):
        """Return every check run GitHub reported for one commit SHA.

        Reading check runs needs no branch-protection or ruleset access, so this
        is the head-eligibility signal the automation's own token can always
        see. The endpoint answers with an object rather than a list, so it
        paginates through ``gh`` instead of ``gh_pages``.
        """
        runs = []
        for page in range(1, 101):
            data = self.gh(
                "GET", f"/commits/{sha}/check-runs?per_page=100&page={page}"
            )
            batch = data.get("check_runs") or []
            runs.extend(batch)
            if len(runs) >= int(data.get("total_count") or 0) or not batch:
                return runs
        raise RuntimeError("GitHub check-run pagination exceeded limit")

    def required_check_contexts(self, number):
        """Return the status contexts GitHub marks required on one pull request.

        `isRequired` is the merge-policy source of truth and is PR-scoped, so it
        is correct for a stacked PR whose symbolic base branch carries no branch
        rules of its own. It is a field on each context in the head's status
        check rollup and takes the pull request number, so a single GraphQL query
        answers with the required check runs and any required commit statuses,
        each already attributed to the exact head. Only contexts GitHub itself
        reports as required are returned, so an optional workflow that fails
        before creating any check run is not present.
        """
        owner, name = self.repository.split("/", 1)
        query = (
            "query($owner:String!,$name:String!,$number:Int!){"
            "repository(owner:$owner,name:$name){"
            "pullRequest(number:$number){"
            "commits(last:1){"
            "nodes{"
            "commit{"
            "statusCheckRollup{"
            "contexts(first:100){"
            "pageInfo{hasNextPage}"
            "nodes{"
            "__typename"
            " ... on CheckRun{name isRequired(pullRequestNumber:$number)}"
            " ... on StatusContext{context isRequired(pullRequestNumber:$number)}"
            "}"
            "}"
            "}"
            "}"
            "}"
            "}"
            "}"
            "}"
            "}"
        )
        data = self.api(
            "POST",
            "/graphql",
            body={
                "query": query,
                "variables": {"owner": owner, "name": name, "number": number},
            },
        )
        if data.get("errors"):
            raise RuntimeError(
                f"GitHub required-check query failed: {data['errors'][0].get('message')}"
            )
        nodes = (
            (((data.get("data") or {}).get("repository") or {}).get("pullRequest") or {})
            .get("commits", {})
            .get("nodes")
        ) or []
        contexts = (
            ((nodes[0].get("commit") or {}).get("statusCheckRollup") or {}).get(
                "contexts", {}
            )
            if nodes
            else {}
        )
        if (contexts.get("pageInfo") or {}).get("hasNextPage"):
            raise RuntimeError(
                "GitHub required-check rollup exceeds one page; the required "
                "set may be incomplete"
            )
        return [
            {
                "name": node.get("name") or node.get("context"),
                "kind": node.get("__typename"),
            }
            for node in (contexts.get("nodes") or [])
            if node.get("isRequired") and (node.get("name") or node.get("context"))
        ]

    def workflow_runs(self, sha):
        """Return every Actions workflow run GitHub reported for one commit SHA.

        A workflow that fails before any job starts - a workflow-level error, or
        a `pull_request` run whose jobs never materialize - still records a
        failed check suite, but it contributes no check runs, so the commit's
        check-run rollup and `gh pr checks` both report success. Reading the
        workflow runs directly is the only way the gate can see that failure.
        Like the check-run endpoint this answers with an object, so it paginates
        manually.
        """
        runs = []
        for page in range(1, 101):
            data = self.gh(
                "GET", f"/actions/runs?head_sha={sha}&per_page=100&page={page}"
            )
            batch = data.get("workflow_runs") or []
            runs.extend(batch)
            if len(runs) >= int(data.get("total_count") or 0) or not batch:
                return runs
        raise RuntimeError("GitHub workflow-run pagination exceeded limit")

    def completed_dependency(self, number):
        if number in self._completed_dependencies:
            return self._completed_dependencies[number]
        try:
            dependency = self.gh("GET", f"/issues/{number}")
        except HTTPError as exc:
            if exc.code == 404:
                return False
            raise
        completed = (
            dependency["state"] == "closed"
            and dependency.get("state_reason") == "completed"
        )
        self._completed_dependencies[number] = completed
        return completed

    def dependencies_complete(self, issue):
        """Honor explicit Depends on lines; unknown/incomplete issues remain blocked."""
        for line in re.findall(
            "^Depends on:\\s*(.+)$",
            issue.get("body") or "",
            re.MULTILINE | re.IGNORECASE,
        ):
            for number in re.findall("#(\\d+)", line):
                if not self.completed_dependency(number):
                    return False
        return True

    def gh_pages(self, endpoint):
        split = urlsplit(endpoint)
        return github_paginate(
            self.token,
            f"/repos/{self.repository}" + split.path,
            params=dict(parse_qsl(split.query)),
        )


def run_repositories(automation_type, conversation=None, dispatcher=None):
    parser = argparse.ArgumentParser(description=automation_type.__doc__)
    parser.add_argument("--github-token-secret")
    args = parser.parse_args()
    config = json.loads(Path("config.json").read_text())
    token_name = args.github_token_secret or config.get(
        "github_token_secret", "GITHUB_PERSONAL_ACCESS_TOKEN"
    )
    repositories = config.get("repos") or [config["repository"]]
    failures = []
    for repository in repositories:
        options = dict(
            github_token_secret=token_name,
            repository=repository,
            conversation=conversation,
        )
        if dispatcher is not None:
            options["dispatcher"] = dispatcher
        automation = automation_type(**options)
        try:
            automation.run()
        except Exception as exc:  # noqa: BLE001 - one repository must not block others
            failures.append(repository)
            print(
                json.dumps({"repository": repository, "error": type(exc).__name__}),
                flush=True,
            )
    if failures:
        raise RuntimeError("Automation failed for: " + ", ".join(failures))
    return str(conversation.id) if conversation else None

triage_publication.py:
"""Pure triage contracts and optimistic, fail-closed GitHub publication."""

import argparse
import hashlib
import json
import re
from pathlib import Path
from urllib.parse import quote, unquote

from github_client import GitHubRepository

START = "<!-- openhands-ai-triage:start -->"
END = "<!-- openhands-ai-triage:end -->"
VERSION = 3
DISCLOSURE = "_Generated by an AI agent (OpenHands) on behalf of the automation owner._"


def split_body(body):
    body = body or ""
    if START not in body and END not in body:
        return body, "", ""
    if body.count(START) != 1 or body.count(END) != 1:
        raise ValueError("Ambiguous managed markers; human repair required")
    start, end = body.index(START), body.index(END)
    if end < start:
        raise ValueError("Reversed managed markers")
    return body[:start], body[start : end + len(END)], body[end + len(END) :]


def author_body(body):
    before, _, after = split_body(body)
    return (before + after).rstrip()


def owned_comment(comment, login):
    return (
        bool(login)
        and (comment.get("user") or {}).get("login") == login
        and bool(
            re.search(r"<!-- triage-source:[a-f0-9]{64} -->", comment.get("body") or "")
        )
    )


def readiness_comment(comment):
    return (comment.get("user") or {}).get(
        "login"
    ) == "github-actions[bot]" and "<!-- issue-readiness-check -->" in (
        comment.get("body") or ""
    )


def readiness_transitions(repo, number, login):
    return [
        (e.get("id"), e.get("event"), e.get("created_at"))
        for e in repo.gh_pages(f"/issues/{number}/timeline")
        if e.get("event") in {"labeled", "unlabeled"}
        and (e.get("label") or {}).get("name") == "ready-for-dev"
        and (e.get("actor") or {}).get("login") != login
        and (e.get("actor") or {}).get("login") != "github-actions[bot]"
    ]


def fingerprint(issue, comments, login, transitions=(), policy=None):
    return hashlib.sha256(
        json.dumps(
            [
                VERSION,
                issue["title"],
                author_body(issue.get("body")),
                list(transitions),
                policy,
                [
                    (
                        c["id"],
                        c.get("updated_at"),
                        c.get("body"),
                        (c.get("user") or {}).get("login"),
                    )
                    for c in comments
                    if not owned_comment(c, login) and not readiness_comment(c)
                ],
            ],
            sort_keys=True,
        ).encode()
    ).hexdigest()


def parse_recommendation(value):
    if isinstance(value, str):
        value = json.loads(value)
    required = {"decision", "priority", "scope", "non_goals", "criteria", "questions"}
    if not isinstance(value, dict) or set(value) != required:
        raise ValueError("Recommendation must contain exactly the documented fields")
    if value["decision"] not in ("ready", "decision_needed") or value[
        "priority"
    ] not in ("high", "medium", "low"):
        raise ValueError("Invalid decision or priority")
    for key in ("scope", "non_goals"):
        if not isinstance(value[key], str) or not value[key].strip():
            raise ValueError(f"Missing {key}")
    for key in ("criteria", "questions"):
        if not isinstance(value[key], list) or any(
            not isinstance(s, str) or not s.strip() for s in value[key]
        ):
            raise ValueError(f"Invalid {key}")
    if value["decision"] == "ready":
        if not value["criteria"] or value["questions"]:
            raise ValueError("Ready requires criteria and no open questions")
    elif not value["questions"] or value["criteria"]:
        raise ValueError(
            "Decision needed requires questions and no provisional criteria"
        )
    if "<!--" in json.dumps(value) or len(json.dumps(value)) > 20000:
        raise ValueError("Embedded markers or oversized recommendation")
    return value


def render(body, recommendation, digest):
    r = parse_recommendation(recommendation)
    before, old, after = split_body(body)
    marker = f"<!-- triage-source:{digest} -->"
    if not re.fullmatch(r"[a-f0-9]{64}", digest):
        raise ValueError("Invalid input digest")
    if r["decision"] == "decision_needed":
        return before + after, f"{DISCLOSURE}\n\n### Decision needed\n" + "\n".join(
            f"- {q}" for q in r["questions"]
        ) + f"\n\n{marker}"
    section = (
        f"{START}\n## OpenHands AI triage\n{DISCLOSURE}\n\n"
        f"### Scope\n{r['scope']}\n\n### Non-goals\n{r['non_goals']}\n\n"
        "### Acceptance Criteria\n"
        + "\n".join(f"- [ ] {c}" for c in r["criteria"])
        + f"\n\n{marker}\n{END}"
    )
    return before + ("" if old else "\n\n") + section + after, None


def writer_policy_allows(repo, login):
    """Only deployment-audited writer-only policies are supported, never repo code."""
    policy = repo.config.get("triage_readiness_policies", {}).get(repo.repository, {})
    if policy.get("mode") != "authorized-writers" or not policy.get("files"):
        return False
    for path, sha in policy["files"].items():
        if not re.fullmatch(r"[a-f0-9]{40}", sha):
            return False
        current = repo.gh("GET", f"/contents/{quote(path, safe='/')}")
        if current.get("sha") != sha:
            return False
    permission = repo.gh("GET", f"/collaborators/{quote(login, safe='')}/permission")
    return permission.get("permission") in {"write", "maintain", "admin"}


def publish(repo, number, expected, recommendation):
    r = parse_recommendation(recommendation)
    login = repo.api("GET", "/user")["login"]
    path = f"/issues/{number}"
    initial = repo.gh("GET", path)
    comments = repo.gh_pages(path + "/comments")
    if initial.get("state") != "open" or "pull_request" in initial:
        raise ValueError("Issue no longer eligible")
    if (
        fingerprint(
            initial,
            comments,
            login,
            readiness_transitions(repo, number, login),
            repo.config.get("triage_readiness_policies"),
        )
        != expected
    ):
        raise ValueError("Human inputs changed; recompute recommendation")
    body, comment = render(initial.get("body"), r, expected)
    receipt = f"<!-- triage-complete:{expected} -->"
    body = body.replace(receipt, "")
    labels = {label["name"] for label in initial.get("labels", [])}
    writes = 0

    def guarded(method, target, data=None):
        nonlocal initial, writes
        current = repo.gh("GET", path)
        fresh_comments = repo.gh_pages(path + "/comments")
        if (
            current.get("state") != "open"
            or {l["name"] for l in current.get("labels", [])} != labels
            or current.get("body") != initial.get("body")
            or fingerprint(
                current,
                fresh_comments,
                login,
                readiness_transitions(repo, number, login),
                repo.config.get("triage_readiness_policies"),
            )
            != expected
        ):
            raise ValueError("Inputs changed before write; recompute recommendation")
        result = repo.gh(method, target, data)
        writes += 1
        if target == path and method == "PATCH":
            initial = {**initial, "body": data["body"]}
        if target == path + "/labels" and method == "POST":
            labels.update(data["labels"])
        elif target.startswith(path + "/labels/") and method == "DELETE":
            labels.discard(unquote(target.rsplit("/", 1)[1]))
        return result

    # Revoke readiness before changing its supporting criteria.
    labels = {label["name"] for label in initial.get("labels", [])}
    allowed = r["decision"] == "ready" and writer_policy_allows(repo, login)
    if "ready-for-dev" in labels and r["decision"] == "decision_needed":
        guarded("DELETE", path + "/labels/ready-for-dev")
    completed_body = (
        body.replace(END, receipt + "\n" + END) if r["decision"] == "ready" else body
    )
    if body != (initial.get("body") or "") and completed_body != (
        initial.get("body") or ""
    ):
        guarded("PATCH", path, {"body": body})
    own = [c for c in comments if owned_comment(c, login)]
    if comment and not any(
        c.get("body") in (comment, comment + "\n" + receipt) for c in own
    ):
        if own:
            guarded("PATCH", f"/issues/comments/{own[0]['id']}", {"body": comment})
            own = own[1:]
        else:
            guarded("POST", path + "/comments", {"body": comment})
    else:
        own = [
            c
            for c in own
            if c.get("body")
            not in (comment, (comment + "\n" + receipt) if comment else None)
        ]
    for c in own:
        guarded("DELETE", f"/issues/comments/{c['id']}")
    priority = "priority:" + r["priority"]
    for other in sorted(
        labels
        & {"priority:normal", "priority:high", "priority:medium", "priority:low"}
        - {priority}
    ):
        guarded("DELETE", path + "/labels/" + quote(other, safe=""))
    if priority not in labels:
        guarded("POST", path + "/labels", {"labels": [priority]})
    if allowed and "ready-for-dev" not in labels and writer_policy_allows(repo, login):
        guarded("POST", path + "/labels", {"labels": ["ready-for-dev"]})
    if r["decision"] == "ready":
        if completed_body != (initial.get("body") or ""):
            guarded("PATCH", path, {"body": completed_body})
    elif comment:
        current_comments = repo.gh_pages(path + "/comments")
        target = next(
            c
            for c in current_comments
            if owned_comment(c, login) and expected in c.get("body", "")
        )
        completed_comment = comment + "\n" + receipt
        if target.get("body") != completed_comment:
            guarded(
                "PATCH", f"/issues/comments/{target['id']}", {"body": completed_comment}
            )
    return {"writes": writes, "readiness_policy_allowed": allowed}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--config", required=True)
    parser.add_argument("--repository", required=True)
    parser.add_argument("--number", required=True, type=int)
    parser.add_argument("--expected", required=True)
    parser.add_argument("--recommendation", required=True)
    parser.add_argument("--github-token-secret", required=True)
    args = parser.parse_args()
    config = json.loads(Path(args.config).read_text())
    if args.repository not in (config.get("repos") or [config.get("repository")]):
        raise ValueError("Repository not allowed by deployment")
    repo = GitHubRepository(
        args.config,
        repository=args.repository,
        github_token_secret=args.github_token_secret,
    )
    print(
        json.dumps(
            publish(
                repo, args.number, args.expected, Path(args.recommendation).read_text()
            )
        )
    )


if __name__ == "__main__":
    main()
